import { useCallback, useEffect, useState } from 'react';
import Head from 'next/head';
import { adminFetch, adminMutation, apiErrorMessage } from '@/lib/admin-client';

type Report = { id: string; report: string; frequency: 'daily' | 'weekly' | 'monthly'; recipients: string[]; hour_utc: number; format: 'csv' | 'json'; enabled: boolean; last_run_at?: string | null; last_status?: string | null };
type Run = { id?: string; created_at?: string; status?: string; detail?: string; recipients?: string[] };
const reportLabels: Record<string, string> = { revenue: 'الإيرادات', commissions: 'العمولات', funnels: 'مسارات التحويل', cohorts: 'الاحتفاظ cohorts', anomalies: 'التنبيهات', provider_league: 'دوري المزودين' };

export default function ScheduledReportsPage() {
  const [reports, setReports] = useState<Report[]>([]); const [runs, setRuns] = useState<Record<string, Run[]>>({}); const [form, setForm] = useState({ report: 'revenue', frequency: 'weekly', recipients: '', hour_utc: '4', format: 'csv' }); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [error, setError] = useState('');
  const load = useCallback(async () => { setLoading(true); setError(''); try { setReports(await adminFetch<Report[]>('/scheduled-reports')); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر تحميل التقارير المجدولة.')); } finally { setLoading(false); } }, []);
  useEffect(() => { void load(); }, [load]);
  async function create(event: React.FormEvent) { event.preventDefault(); const recipients = form.recipients.split(/[،,;\s]+/).map((entry) => entry.trim()).filter(Boolean); setSaving(true); try { await adminMutation('/scheduled-reports', 'POST', { ...form, recipients, hour_utc: Number(form.hour_utc), enabled: true }); setForm({ report: 'revenue', frequency: 'weekly', recipients: '', hour_utc: '4', format: 'csv' }); await load(); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر حفظ التقرير المجدول.')); } finally { setSaving(false); } }
  async function toggle(report: Report) { setSaving(true); try { await adminMutation(`/scheduled-reports/${encodeURIComponent(report.id)}`, 'PATCH', { enabled: !report.enabled }); await load(); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر تعديل حالة التقرير.')); } finally { setSaving(false); } }
  async function runNow(report: Report) { if (!window.confirm(`سيتم حساب تقرير «${reportLabels[report.report] || report.report}» وإرساله فعلياً إلى المستلمين. متابعة؟`)) return; setSaving(true); try { const result = await adminMutation<{ ok: boolean; detail?: string }>(`/scheduled-reports/${encodeURIComponent(report.id)}/run`, 'POST'); if (!result.ok) setError(`لم يكتمل التسليم: ${result.detail || 'راجع سجل التشغيل'}`); await showRuns(report); await load(); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر تشغيل التقرير.')); } finally { setSaving(false); } }
  async function showRuns(report: Report) { try { const data = await adminFetch<{ data: Run[] }>(`/scheduled-reports/${encodeURIComponent(report.id)}/runs`); setRuns((current) => ({ ...current, [report.id]: data.data || [] })); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر تحميل سجل تسليم التقرير.')); } }
  async function remove(report: Report) { const reason = window.prompt('سبب حذف التقرير المجدول (5 أحرف على الأقل):'); if (!reason || reason.trim().length < 5 || !window.confirm('سيحذف التقرير من الجدولة. متابعة؟')) return; setSaving(true); try { await adminMutation(`/scheduled-reports/${encodeURIComponent(report.id)}`, 'DELETE', { reason: reason.trim() }); await load(); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر حذف التقرير.')); } finally { setSaving(false); } }
  return <><Head><title>التقارير المجدولة | نبض</title></Head><section dir="rtl" className="space-y-6 p-6 md:p-8"><header><h1 className="text-3xl font-bold">التقارير المجدولة</h1><p className="mt-1 text-sm text-slate-500">يحسب backend المحتوى الحقيقي ويرسل المرفق إلى البريد، ثم يسجل النتيجة في سجل تشغيل قابل للمراجعة.</p></header>{error ? <p role="alert" className="rounded-lg bg-rose-50 p-3 text-rose-700">{error}</p> : null}<form onSubmit={create} className="grid gap-3 rounded-2xl border bg-white p-5 shadow-sm md:grid-cols-5"><label className="text-sm">التقرير<select value={form.report} onChange={(e) => setForm({ ...form, report: e.target.value })} className="mt-1 w-full rounded border p-2">{Object.entries(reportLabels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></label><label className="text-sm">التواتر<select value={form.frequency} onChange={(e) => setForm({ ...form, frequency: e.target.value })} className="mt-1 w-full rounded border p-2"><option value="daily">يومي</option><option value="weekly">أسبوعي</option><option value="monthly">شهري</option></select></label><label className="text-sm">الساعة UTC<input value={form.hour_utc} onChange={(e) => setForm({ ...form, hour_utc: e.target.value })} type="number" min="0" max="23" className="mt-1 w-full rounded border p-2"/></label><label className="text-sm">الصيغة<select value={form.format} onChange={(e) => setForm({ ...form, format: e.target.value })} className="mt-1 w-full rounded border p-2"><option value="csv">CSV</option><option value="json">JSON</option></select></label><label className="text-sm md:col-span-2">المستلمون<input required value={form.recipients} onChange={(e) => setForm({ ...form, recipients: e.target.value })} dir="ltr" className="mt-1 w-full rounded border p-2" placeholder="ops@example.com, finance@example.com"/></label><button disabled={saving} className="self-end rounded bg-teal-700 px-4 py-2 font-bold text-white disabled:opacity-50">إضافة الجدولة</button></form><div className="space-y-4">{loading ? <p className="rounded-2xl border bg-white p-10 text-center text-slate-500">جارٍ تحميل الجدولات…</p> : reports.length ? reports.map((report) => <article key={report.id} className="rounded-2xl border bg-white p-5 shadow-sm"><div className="flex flex-wrap items-start justify-between gap-4"><div><h2 className="text-lg font-bold">{reportLabels[report.report] || report.report}</h2><p className="mt-1 text-sm text-slate-500">{report.frequency} · الساعة {report.hour_utc}:00 UTC · {report.format.toUpperCase()}</p><p className="mt-1 text-xs text-slate-500" dir="ltr">{report.recipients.join(', ')}</p><p className="mt-1 text-xs text-slate-500">آخر تشغيل: {report.last_run_at ? new Date(report.last_run_at).toLocaleString('ar-SA') : 'لم يُشغل'} · {report.last_status || '—'}</p></div><div className="flex flex-wrap gap-2"><button disabled={saving} onClick={() => void runNow(report)} className="rounded bg-teal-700 px-3 py-2 text-sm font-bold text-white">تشغيل الآن</button><button disabled={saving} onClick={() => void toggle(report)} className="rounded border px-3 py-2 text-sm">{report.enabled ? 'إيقاف' : 'تفعيل'}</button><button disabled={saving} onClick={() => void showRuns(report)} className="rounded border px-3 py-2 text-sm">سجل التسليم</button><button disabled={saving} onClick={() => void remove(report)} className="rounded border border-rose-300 px-3 py-2 text-sm text-rose-700">حذف</button></div></div>{runs[report.id] ? <div className="mt-4 overflow-x-auto rounded-lg bg-slate-50 p-3"><table className="min-w-full text-right text-xs"><thead><tr><th className="p-1">التاريخ</th><th className="p-1">الحالة</th><th className="p-1">التفاصيل</th></tr></thead><tbody>{runs[report.id].map((run, index) => <tr key={run.id || index}><td className="p-1">{run.created_at ? new Date(run.created_at).toLocaleString('ar-SA') : '—'}</td><td className="p-1">{run.status || '—'}</td><td className="p-1">{run.detail || '—'}</td></tr>)}</tbody></table></div> : null}</article>) : <p className="rounded-2xl border bg-white p-10 text-center text-slate-500">لا توجد تقارير مجدولة.</p>}</div></section></>;
}
